{
  "cases": [
    {
      "opening": "我打算这周每天跑3公里，但实际只跑了两次。",
      "followups": [
        {
          "text": "我这周跑步的完成情况怎么样?",
          "new_user":false
        }
      ],
      "requirement": "必须正确说出用户计划每天跑3公里，但实际只跑了两次，不能多说或少说。",
      "theme": "计划 vs 实际执行"
    },
    {
      "opening": "我以前喜欢喝全脂牛奶，最近改成喝脱脂牛奶了。",
      "followups": [
        {
          "text": "我现在喝什么类型的牛奶?",
          "new_user":false
        }
      ],
      "requirement": "必须正确回忆用户已把牛奶类型从全脂改为脱脂，不能混淆为原来的全脂。",
      "theme": "偏好更新"
    },
    {
      "opening": "我已经不再吃辣了，因为胃不舒服。",
      "followups": [
        {
          "text": "我以前有没有吃辣?",
          "new_user":false
        }
      ],
      "requirement": "必须正确回忆用户以前吃辣，但现在已经不再吃辣，不能说仍在吃辣。",
      "theme": "否定信息"
    },
    {
      "opening": "我妈妈最近在吃血压药，我想了解她的血压情况。",
      "followups": [
        {
          "text": "我妈妈的血压最近稳定吗?",
          "new_user":false
        }
      ],
      "requirement": "必须正确指出询问的是用户的妈妈，而非用户本人，并说明没有提供最近的血压数值。",
      "theme": "不同人物归属"
    },
    {
      "opening": "我上周开始每天走1万步。",
      "followups": [
        {
          "text": "我想查看今天的步数记录。",
          "new_user":true
        }
      ],
      "requirement": "必须说明该用户是新用户，没有历史步数记录，不能假设已有数据。",
      "theme": "跨用户隔离"
    },
    {
      "opening": "我上个月开始使用睡眠追踪器。",
      "followups": [
        {
          "text": "我从什么时候开始使用睡眠追踪器的?",
          "new_user":false
        }
      ],
      "requirement": "必须回答用户上个月开始使用睡眠追踪器，但不提供具体日期。",
      "theme": "部分时间信息"
    },
    {
      "opening": "我打算这周去医院做血液检查，但还没去。",
      "followups": [
        {
          "text": "我的血液检查结果出来了吗?",
          "new_user":false
        }
      ],
      "requirement": "必须说明用户尚未完成血液检查，因而没有检查结果。",
      "theme": "未完成随访"
    },
    {
      "opening": "我上周做了体检，本周又做了一次血常规。",
      "followups": [
        {
          "text": "我这周做了什么检查?",
          "new_user":false
        }
      ],
      "requirement": "必须正确指出用户本周做的是血常规检查，而不是上周的体检。",
      "theme": "两件相似事件区分"
    },
    {
      "opening": "我每天提醒自己要喝水八杯，但实际只喝五杯。",
      "followups": [
        {
          "text": "我今天的喝水量是多少?",
          "new_user":false
        }
      ],
      "requirement": "必须正确说出用户今天喝了五杯水，而不是八杯。",
      "theme": "提醒 vs 实际行为"
    },
    {
      "opening": "我昨天做了瑜伽课，但记不得老师名字。",
      "followups": [
        {
          "text": "我的瑜伽课老师是谁?",
          "new_user":false
        }
      ],
      "requirement": "必须说明用户未提供瑜伽课老师的名字。",
      "theme": "信息缺失"
    },
    {
      "opening": "我爸爸有糖尿病，我最近在帮他记录血糖。",
      "followups": [
        {
          "text": "我爸爸的血糖水平最近怎么样?",
          "new_user":false
        }
      ],
      "requirement": "必须正确指出询问的是用户的爸爸，而非用户本人，并说明没有提供最近的血糖数据。",
      "theme": "多人物关系混淆"
    },
    {
      "opening": "我上个月的体重是70公斤，这个月降到68公斤。",
      "followups": [
        {
          "text": "我的体重这月是多少?",
          "new_user":false
        }
      ],
      "requirement": "必须正确说出用户当前体重为68公斤，而不是上个月的70公斤。",
      "theme": "跨会话信息对比"
    }
  ]
}
